# Let me find all triangular patterns in Demo 2 output
# A triangle pattern might look like:
#     X
#    XXX
#   XXXXX
# or variations

def find_triangles(grid, marker_val):
    triangles = []
    h, w = len(grid), len(grid[0])

    # Look for triangle patterns
    # Type 1: upright triangle (tall point down at top, wide at bottom)
    for r in range(h):
        for start_c in range(w):
            # Check for potential triangle apex
            for size in range(3, min(w, h)):  # Triangle size
                triangle = []
                for offset in range(size):
                    row_r = r + offset
                    row_c = start_c + offset
                    if row_r >= h or row_c >= w:
                        break
                    if grid[row_r][row_c] == marker_val:
                        triangle.append((row_r, row_c))
                    else:
                        break
                if len(triangle) >= 3:
                    triangles.append(triangle)
    return triangles

