def find_regions(grid, target_val):
    """Find connected regions of a specific value, marking if they touch the edge"""
    h, w = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(h):
        for c in range(w):
            if (r, c) not in visited and grid[r][c] == target_val:
                # BFS to find connected region
                region = {}
                stack = [(r, c)]
                while stack:
                    cell = stack.pop()
                    if cell in visited:
                        continue
                    visited.add(cell)
                    rr, cc = cell
                    region[cell] = (rr, cc)
                    # Check edges and 4-conn
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
